export const aggregateMaxOverlap = (items, keyFn) => {
    const result = items.reduce((overlaps, item) => {
        const key = keyFn(item);
        overlaps[key] = Math.max(overlaps[key] ?? 0, item.maxLevel);
        return overlaps
    }, []);
    for (let i = 0; i < result.length; i += 1) {
        result[i] ?? (result[i] = 0)
    }
    return result
};
